const suspendedMachinesOf = `-- name: SuspendedMachinesOf :many
SELECT id FROM identities WHERE suspended_by_deletion = ? ORDER BY id
`

// The machine identities a request suspended, which its cancel restores.
func (q *Queries) SuspendedMachinesOf(ctx context.Context, suspendedByDeletion sql.NullString) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, suspendedMachinesOf, suspendedByDeletion)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

