const tombstoneReaders = `-- name: TombstoneReaders :many
SELECT r.organization_id, r.identity_id, i.name, r.removed_at FROM audit_tombstone_readers r
JOIN identities i ON i.id = r.identity_id
JOIN organizations o ON o.id = r.organization_id AND o.deleted_at IS NOT NULL
ORDER BY r.identity_id
`

type TombstoneReadersRow struct {
	OrganizationID string
	IdentityID     string
	Name           string
	RemovedAt      sql.NullInt64
}

// Every reader of the deleted Organizations, removed or not.
func (q *Queries) TombstoneReaders(ctx context.Context) ([]TombstoneReadersRow, error) {
	rows, err := q.db.QueryContext(ctx, tombstoneReaders)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TombstoneReadersRow
	for rows.Next() {
		var i TombstoneReadersRow
		if err := rows.Scan(
			&i.OrganizationID,
			&i.IdentityID,
			&i.Name,
			&i.RemovedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
